ret = generic_write_checks(iocb, from);

if (iov_iter_count(from) > 0) {
	size_t count = iov_iter_count(from);
	size_t missed = fault_in_iov_iter_readable(from, count);

	if (missed == count)
		return -EFAULT;
	if (missed)
		iov_iter_truncate(from, count - missed);
}

